#!/usr/bin/env python3
"""Compute deterministic ground truth for CSX-279_Q2."""

from __future__ import annotations

import json
from pathlib import Path


TASK_ID = "CSX-279_Q2"
EVENT_ID = "CSX-279"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_002_Locked_event_anchor_2015-2016_El_Nino_and_Pacific_Island_drought_emergencies.json",
    "data/physical_hazard/physical_hazard_006_NOAA_CPC_ONI_ASCII.txt",
    "data/physical_hazard/physical_hazard_008_NOAA_PSL_SOI_data.data",
    "data/physical_hazard/physical_hazard_009_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_010_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_011_CHIRPS_daily_event_accumulated_precipitation.json",
]


def read_text(rel_path: str) -> str:
    return (PACKAGE_DIR / rel_path).read_text(encoding="utf-8", errors="ignore")


def read_json(rel_path: str) -> dict:
    return json.loads(read_text(rel_path))


def compact_size(value: dict) -> int:
    return len(json.dumps(value, ensure_ascii=True, separators=(",", ":")))


def precip_ratio(payload: dict, prefix: str) -> dict:
    stats = payload["stats"]
    min_mm = float(stats[f"{prefix}_event_precip_mm_min"])
    mean_mm = float(stats[f"{prefix}_event_precip_mm_mean"])
    return {
        "dataset": payload["dataset"],
        "start": payload["start"],
        "end": payload["end"],
        "min_mm": min_mm,
        "mean_mm": mean_mm,
        "ratio": min_mm / mean_mm,
    }


def parse_oni(text: str, seasons: set[tuple[str, int]]) -> dict:
    values: dict[str, float] = {}
    for line in text.splitlines():
        parts = line.split()
        if len(parts) != 4 or parts[0] == "SEAS":
            continue
        season = parts[0]
        year = int(parts[1])
        if (season, year) in seasons:
            values[f"{season}_{year}"] = float(parts[3])
    selected = list(values.values())
    return {
        "values": values,
        "count": len(selected),
        "peak_c": max(selected),
        "mean_c": sum(selected) / len(selected),
    }


def parse_soi(text: str, months_by_year: dict[int, list[int]]) -> dict:
    month_labels = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    values: dict[str, float] = {}
    for line in text.splitlines():
        parts = line.split()
        if len(parts) != 13:
            continue
        try:
            year = int(parts[0])
        except ValueError:
            continue
        if year not in months_by_year:
            continue
        for month in months_by_year[year]:
            values[f"{month_labels[month - 1]}_{year}"] = float(parts[month])
    selected = list(values.values())
    below_zero = sum(1 for value in selected if value < 0)
    return {
        "values": values,
        "count": len(selected),
        "below_zero_count": below_zero,
        "below_zero_frac": below_zero / len(selected),
        "mean": sum(selected) / len(selected),
        "minimum": min(selected),
    }


def rounded_calculation() -> dict:
    event_meta = read_json(SOURCE_FILES[0])
    anchor = read_json(SOURCE_FILES[1])
    gpm = precip_ratio(read_json(SOURCE_FILES[5]), "gpm")
    chirps = precip_ratio(read_json(SOURCE_FILES[6]), "chirps")
    era5_stats = read_json(SOURCE_FILES[4])["stats"]

    oni = parse_oni(
        read_text(SOURCE_FILES[2]),
        {
            ("SON", 2015),
            ("OND", 2015),
            ("NDJ", 2015),
            ("DJF", 2016),
            ("JFM", 2016),
            ("FMA", 2016),
            ("MAM", 2016),
        },
    )
    soi = parse_soi(read_text(SOURCE_FILES[3]), {2015: [10, 11, 12], 2016: [1, 2, 3, 4]})

    r_gpm = gpm["ratio"]
    r_chirps = chirps["ratio"]
    dry_ratio_mean = (r_gpm + r_chirps) / 2.0
    dry_deficit_mean = 1.0 - dry_ratio_mean
    agreement_delta = abs(r_gpm - r_chirps)
    oni_peak_c = oni["peak_c"]
    soi_neg_frac = soi["below_zero_frac"]
    tmax_spread_c = float(era5_stats["temperature_2m_max_c_max"]) - float(era5_stats["temperature_2m_max_c_mean"])

    dry_component = min(dry_deficit_mean / 0.70, 1.0)
    agreement_component = max(0.0, 1.0 - agreement_delta / 0.01)
    oni_component = min(oni_peak_c / 2.0, 1.0)
    temperature_component = min(tmax_spread_c / 4.0, 1.0)
    ledger_score = 100.0 * (
        0.35 * dry_component
        + 0.20 * agreement_component
        + 0.25 * oni_component
        + 0.10 * soi_neg_frac
        + 0.10 * temperature_component
    )

    thresholds = {
        "dry_deficit_gte_0_70": dry_deficit_mean >= 0.70,
        "agreement_delta_lte_0_01": agreement_delta <= 0.01,
        "oni_peak_gte_2_0": oni_peak_c >= 2.0,
        "soi_neg_frac_gte_0_80": soi_neg_frac >= 0.80,
        "tmax_spread_gte_4_0": tmax_spread_c >= 4.0,
    }
    answer = "all_5_thresholds_met" if all(thresholds.values()) else "thresholds_incomplete"

    primary_gt = {
        "answer": answer,
        "dry_ratio_mean": round(dry_ratio_mean, 3),
        "dry_deficit_mean": round(dry_deficit_mean, 3),
        "agreement_delta": round(agreement_delta, 3),
        "oni_peak_c": round(oni_peak_c, 2),
        "soi_neg_frac": round(soi_neg_frac, 3),
        "tmax_spread_c": round(tmax_spread_c, 2),
        "ledger_score": round(ledger_score, 2),
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "task_type": "numeric",
        "target_family": "enso_drought_threshold_ledger",
        "evaluation_mode": "deterministic",
        "primary_gt": primary_gt,
        "event": {
            "event_id": EVENT_ID,
            "event_name": event_meta["event_name"],
            "event_window": (
                f"{anchor['temporal_window']['start_date']} to {anchor['temporal_window']['end_date']}"
            ),
            "rainfall_slice": f"{gpm['start']} to {gpm['end']}",
        },
        "calculation": {
            "precipitation": {
                "gpm_ratio": round(r_gpm, 6),
                "chirps_ratio": round(r_chirps, 6),
                "gpm_min_mm": round(gpm["min_mm"], 3),
                "gpm_mean_mm": round(gpm["mean_mm"], 3),
                "chirps_min_mm": round(chirps["min_mm"], 3),
                "chirps_mean_mm": round(chirps["mean_mm"], 3),
            },
            "oni": {
                "values_c": {key: round(value, 2) for key, value in oni["values"].items()},
                "count": oni["count"],
                "mean_c": round(oni["mean_c"], 2),
                "peak_c": round(oni["peak_c"], 2),
            },
            "soi": {
                "values": {key: round(value, 2) for key, value in soi["values"].items()},
                "count": soi["count"],
                "below_zero_count": soi["below_zero_count"],
                "below_zero_frac": round(soi["below_zero_frac"], 3),
                "mean": round(soi["mean"], 2),
                "minimum": round(soi["minimum"], 2),
            },
            "temperature": {
                "max_c": round(float(era5_stats["temperature_2m_max_c_max"]), 2),
                "mean_c": round(float(era5_stats["temperature_2m_max_c_mean"]), 2),
                "spread_c": round(tmax_spread_c, 2),
            },
            "score_components": {
                "dry": round(dry_component, 6),
                "agreement": round(agreement_component, 6),
                "oni": round(oni_component, 6),
                "soi": round(soi_neg_frac, 6),
                "temperature": round(temperature_component, 6),
            },
            "thresholds": thresholds,
            "threshold_count": sum(1 for passed in thresholds.values() if passed),
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Precipitation ratios",
                    "points": 4,
                    "description": "Computes GPM and CHIRPS min/mean ratios before averaging them.",
                    "partial_credit": "Award 2-3 points if both products are used but one ratio or rounding step is wrong.",
                },
                {
                    "name": "Dryness and agreement math",
                    "points": 4,
                    "description": "Derives dry deficit and cross-product agreement delta with correct rounding.",
                    "partial_credit": "Award 2 points if either the deficit or agreement calculation is correct.",
                },
                {
                    "name": "ONI parsing",
                    "points": 4,
                    "description": "Extracts SON 2015 through MAM 2016 ONI values and reports the peak.",
                    "partial_credit": "Award 2-3 points for the correct source and season span with a minor extraction error.",
                },
                {
                    "name": "SOI persistence",
                    "points": 3,
                    "description": "Extracts October 2015 through April 2016 SOI values and computes the below-zero fraction.",
                    "partial_credit": "Award 1-2 points for the correct months with one sign/count error.",
                },
                {
                    "name": "Temperature spread and thresholds",
                    "points": 3,
                    "description": "Computes the ERA5-Land temperature spread and applies the five tests.",
                    "partial_credit": "Award 1-2 points for the correct spread or most threshold booleans.",
                },
                {
                    "name": "Ledger score",
                    "points": 2,
                    "description": "Evaluates the weighted formula and returns the requested compact JSON.",
                    "partial_credit": "Award 1 point for valid compact JSON or a mostly correct score with one component error.",
                },
            ],
        },
        "quality_checks": {
            "primary_gt_top_level_keys": len(primary_gt),
            "primary_gt_compact_bytes": compact_size(primary_gt),
            "threshold_count": sum(1 for passed in thresholds.values() if passed),
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    result = rounded_calculation()
    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(result, indent=2, sort_keys=True, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
